 import { gsap } from 'gsap';
import { color, uv, mix, smoothstep, time, vec3, texture as textureNode } from 'three/tsl';
import { MeshPhysicalNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { THREE, textureLoader, fontAtlas, emit } = ctx;
  const { Group, Mesh, PlaneGeometry, CylinderGeometry, Color, PointLight, AmbientLight, DirectionalLight } = THREE;

  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = new Color(colors.ink ?? '#16161d');
  const paper = new Color(colors.paper ?? '#e8ecf2');
  const accent = new Color(colors.accent ?? '#ff2a38');
  const surface = new Color(colors.surface ?? '#0b0b10');

  const bgGeo = new PlaneGeometry(8, 7);
  const bgMat = new MeshPhysicalNodeMaterial({
    roughness: 0.7,
    metalness: 0.35,
    side: THREE.FrontSide
  });
  const gradientNode = mix(color(ink), color(surface), smoothstep(0.0, 1.0, uv().y));
  bgMat.colorNode = gradientNode;
  const bg = new Mesh(bgGeo, bgMat);
  bg.position.z = -2.5;
  group.add(bg);

  const heroGeo = new CylinderGeometry(0.75, 0.75, 0.22, 64);
  const heroMat = new MeshPhysicalNodeMaterial({
    colorNode: color(surface),
    roughness: 0.55,
    metalness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.25
  });
  const hero = new Mesh(heroGeo, heroMat);
  hero.rotation.x = Math.PI * 0.5;
  hero.position.set(0, -0.2, 0);
  group.add(hero);

  const rim = new PointLight(accent, 0.9, 18);
  rim.position.set(-2.5, 1.2, 2.2);
  group.add(rim);

  const key = new DirectionalLight(paper, 1.1);
  key.position.set(2, 3, 3.5);
  group.add(key);

  const back = new DirectionalLight(accent, 0.5);
  back.position.set(-3, 2, -2);
  group.add(back);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  group.add(textGroup);

  const renderedText = [];
  let yCursor = 1.2;
  for (const item of items) {
    const role = item.role ?? 'body';
    const raw = typeof item.text === 'string' ? item.text : String(item.text ?? '');
    const size = item.typography?.fontSize ?? (role === 'hero' ? 0.62 : role === 'headline' ? 0.34 : role === 'subhead' ? 0.2 : role === 'caption' || role === 'label' ? 0.09 : 0.13);
    const col = new Color(item.color ?? (role === 'accent' ? accent : paper));
    const t = fontAtlas.createText(raw, {
      fontSize: size,
      color: col,
      align: item.align ?? (role === 'caption' || role === 'label' ? 'left' : 'center'),
      letterSpacingPx: role === 'label' ? 0.08 : undefined
    });
    t.position.set(0, yCursor, 1.2);
    textGroup.add(t);
    renderedText.push(t);
    yCursor -= (size * 1.1);
  }

  const timelines = [];

  if (items.length) {
    textGroup.position.y = 0.2;
    const tl = gsap.timeline();
    tl.from(textGroup.position, { y: 0.6, duration: 0.8, ease: 'power3.out' })
       .from(textGroup.children.map(c => c), { opacity: 0, y: 0.15, stagger: 0.08, duration: 0.6, ease: 'power2.out' }, '<');
    timelines.push(tl);
  }

  const settle = gsap.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
  group.scale.set(1.04, 1.04, 1.04);
  timelines.push(settle);

  const spin = gsap.to(hero.rotation, { z: Math.PI * 2, duration: 18, repeat: -1, ease: 'linear' });
  timelines.push(spin);

  const primitiveRefs = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const p of config.cinematicPrimitives) {
      if (ctx.primitives[p.name]) {
        const target = p.params?.target === 'text' ? textGroup : (p.params?.target && group.getObjectByName(p.target) ? group.getObjectByName(p.target) : group);
        const r = ctx.primitives[p.name](target, p.params ?? {});
        primitiveRefs.push(r);
        if (r?.timeline) timelines.push(r.timeline);
        if (r?.cleanup && typeof r.cleanup === 'function') primitiveRefs.push(r);
      }
    }
  }

  if (config.imageUrl) {
    textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.flipY = false;
      tex.needsUpdate = true;
      heroMat.colorNode = textureNode(tex).mul(1.1);
      heroMat.needsUpdate = true;
    }).catch(() => {});
  }

  group.userData.handlers = {
    click: () => {
      const pulse = gsap.timeline();
      pulse.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
        .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.25, ease: 'power2.out' });
      timelines.push(pulse);
      emit('navigate', { to: 'hub-features' });
    },
    hover: () => {
      const tilt = gsap.to(group.rotation, { x: 0.06, duration: 0.3, ease: 'power2.out' });
      timelines.push(tilt);
    },
    hoverOut: () => {
      const reset = gsap.to(group.rotation, { x: 0, y: 0, duration: 0.4, ease: 'power2.out' });
      timelines.push(reset);
    }
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => { if (tl && typeof tl.kill === 'function') tl.kill(); });
    primitiveRefs.forEach((r) => { if (r && typeof r.cleanup === 'function') r.cleanup(); });
    heroGeo.dispose();
    heroMat.dispose();
    bgGeo.dispose();
    bgMat.dispose();
    group.traverse((obj) => {
      if (obj.geometry && obj !== hero && obj !== bg) obj.geometry.dispose();
      if (obj.material && obj !== hero && obj !== bg) {
        if (Array.isArray(obj.material)) obj.material.forEach((m) => m.dispose());
        else obj.material.dispose();
      }
    });
  };

  return group;
}
